code_sketch:
protocol Shape { func area() -> Double }

struct Circle: Shape { let r: Double; func area() -> Double { .pi * r * r } }
struct Square: Shape { let side: Double; func area() -> Double { side * side } }

enum ShapeKind { case circle, square }

func makeShape(_ kind: ShapeKind, size: Double) -> any Shape {
    switch kind {
    case .circle: return Circle(r: size)
    case .square: return Square(side: size)
    }
}

