enum Shape {
    case circle(r: Double)
    case square(side: Double)

    static func make(_ kind: String, size: Double) throws -> Shape {
        switch kind {
        case "circle": return .circle(r: size)
        case "square": return .square(side: size)
        default: throw ShapeError.unknown(kind)
        }
    }

    func area() -> Double {
        switch self {
        case .circle(let r): return .pi * r * r
        case .square(let side): return side * side
        }
    }
}
